function damageParts(ctx,critical){const c=current(),d=derive(c),w=ctx.weapon;let parts=[];if(ctx.spell){const spec=spellMechanic(ctx.spell,ctx.slot||ctx.spell.level,c,ctx.sourceAbility);parts.push({type:spec?.type||'Mágico',formula:spec?.formula||'1d6',label:ctx.spell.name})}else{parts.push({type:w.type,formula:ctx.unarmed?unarmedFormula(c,d):w.formula,label:ctx.label});if(c.sneak&&hasClass(c,'ladino')&&(w.finesse||w.ranged))parts.push({type:w.type,formula:Math.ceil(classLevel(c,'ladino')/2)+'d6',label:'Ataque Furtivo'});if(c.mark)parts.push({type:'Energético',formula:hasClass(c,'guardiao',20)?'1d10':'1d6',label:'Marca do Predador'});if(hasClass(c,'paladino',11)&&(!w.ranged||ctx.unarmed))parts.push({type:'Radiante',formula:'1d8',label:'Golpes Radiantes'})}return parts.map(p=>({...p,roll:roll(p.formula,{critical})}))}
